const plastic=c=>materials.plastic(c,{roughness:.76}),tin=()=>materials.metal(0xc1c0b5,{roughness:.42}),decode=(str,C)=>{const b=atob(str),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);return new C(a.buffer);};
function nativeShell(host){const parts={};for(const data of nativeParts){const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(decode(data.position,Float32Array),3));g.setAttribute('normal',new THREE.BufferAttribute(decode(data.normal,Float32Array),3));g.setIndex(new THREE.BufferAttribute(decode(data.index,Uint32Array),1));g.setAttribute('sourceFaceIndex',new THREE.Uint32BufferAttribute(data.faceIds.flatMap(n=>[n,n,n]),1));const m=new THREE.Mesh(g,plastic(0xe7e6dd));m.name=data.name;m.position.fromArray(data.translation);m.userData={source:'official-structure',nativeSourceSha256:source.sha256,nativePart:data.id,nativeFaceCount:data.triangles,sourceFaceMapping:'sourceFaceIndex attribute retains exact original STL face index',transformation:'Rigid translation only;no remesh/stretch'};host.body.add(m);parts[data.id]=m;}
 const film=solid(host.body,roundedRect(16,28,.15),.04,[0,7,-3.84],plastic(0xe7e5dc),'PaHub v2.0 actual rear adhesive film on native recessed floor');film.userData={role:'physical-label-substrate',thicknessInferred:true};return{...parts,film};}
const outputPinXY=(out,i)=>{const x=-3+2*i,y=-.2,c=Math.cos(out.rotation),s=Math.sin(out.rotation);return[out.position[0]+x*c-y*s,out.position[1]+x*s+y*c];};
function pcbOutline(){const s=new THREE.Shape(),r=4.3,dx=10.2-8,q=Math.acos(dx/r),dy=Math.sqrt(r*r-dx*dx);s.moveTo(-8.2,-22);s.lineTo(-5.3,-22);s.lineTo(-5.3,-17.7);s.lineTo(5.3,-17.7);s.lineTo(5.3,-22);s.lineTo(8.2,-22);s.lineTo(10.2,-20);s.lineTo(10.2,-12-dy);s.absarc(8,-12,r,-q,q,true);s.lineTo(10.2,20);s.lineTo(8.2,22);s.lineTo(-8.2,22);s.lineTo(-10.2,20);s.lineTo(-10.2,-12+dy);s.absarc(-8,-12,r,Math.PI-q,Math.PI+q,true);s.lineTo(-10.2,-20);s.closePath();hole(s,0,-12,2.9);for(const x of[-3,-1,1,3])hole(s,x,-16.9,.38);for(const out of spec.outputs)for(let i=0;i<4;i++){const[x,y]=outputPinXY(out,i);hole(s,x,y,.38);}return s;}
function board(host){const pcb=solid(host.body,pcbOutline(),.8,[0,0,-.2],plastic(0xa52925),'PaHub v2.0 actual exposed red PCB;outline/installation inferred around native retention'),posts=[];for(const x of[-8,8])for(const y of[-20,20.7])posts.push(box(host.body,[1.1,1.1,2.7],[x,y,-1.55],plastic(0xd7d7c9),'PaHub actual PCB post from native rear floor'));
 const arrays=[],arrayLegs=[],arrayPads=[];for(const x of[-2.4,0,2.4]){arrays.push(box(host.body,[2,1,.45],[x,8.7,.875],plastic(0x272c25),'PaHub own visible resistor-array envelope,not exact BOM'));for(const sign of[-1,1])for(let i=0;i<4;i++){const at=[x+(i-1.5)*.45,8.7+sign*.5,.66];arrayLegs.push(box(host.body,[.22,.4,.12],at,tin(),'PaHub actual array retained metal termination'));arrayPads.push(box(host.body,[.34,.5,.025],[at[0],at[1],.6125],tin(),'PaHub actual array supporting solderland'));}}
 const straps=[],terminations=[],pads=[];for(const y of[-4.9,-6.6])for(const x of[-2.4,0,2.4]){straps.push(box(host.body,[1,.7,.4],[x,y,.8],plastic(y<-6?0x9a987f:0x30342d),'PaHub actual fixed resistor strap/passive;not a user switch'));for(const sign of[-1,1]){terminations.push(box(host.body,[.25,.74,.41],[x+sign*.4,y,.805],tin(),'PaHub actual retained strap termination'));pads.push(box(host.body,[.4,.9,.025],[x+sign*.4,y,.6125],tin(),'PaHub actual strap solderland'));}}
 const passives=[],passiveEnds=[];for(const[x,y]of[[-3.9,13],[3.9,14],[3.8,-7.2],[-3.8,-7.2]]){passives.push(box(host.body,[1,.65,.45],[x,y,.825],plastic(0xa59f83),'PaHub own photo-supported passive envelope'));for(const sign of[-1,1])passiveEnds.push(box(host.body,[.25,.7,.46],[x+sign*.4,y,.83],tin(),'PaHub actual supporting passive metal termination'));}return{pcb,posts,arrays,arrayLegs,arrayPads,straps,terminations,pads,passives,passiveEnds};}
function mux(host){const body=box(host.body,[4.4,7.8,1.05],[0,.2,1.205],plastic(0x26322a),'PaHub actual visible24leg mux envelope;PCA/TCA fitted identity unresolved'),legs=[],pads=[];for(const sign of[-1,1])for(let i=0;i<12;i++){const x=sign*2.45,y=.2+(i-5.5)*.6;legs.push(box(host.body,[.85,.25,.12],[x,y,.66],tin(),'PaHub actual visible mux retained perimeter leg'));pads.push(box(host.body,[1.1,.45,.025],[x,y,.6125],tin(),'PaHub actual mux PCB solderland'));}return{body,legs,pads,scope:'Visible physical package only;PCA9548AP/TCA9548A source conflict unresolved,not electrical/BOM'};}
function input(host){const frame=new THREE.Group();frame.position.fromArray(spec.input.position);frame.quaternion.copy(FACE.bottom);frame.name='PaHub v2.0 actual horizontal upstream receiver';host.body.add(frame);const red=plastic(0xb42d29),parts=[],b=(s,p,n,m=red)=>{const q=box(frame,s,p,m,'PaHub input '+n);parts.push(q);return q;},floor=b([10,.65,6.2],[0,-2.275,-3.1],'real dielectric receiving floor'),stop=b([10,4.55,.5],[0,-.325,-5.95],'actual deep backstop'),walls=[-1,1].map(sign=>b([.7,5.2,6.2],[sign*4.65,0,-3.1],'actual receiving wall')),bridge=b([4.8,.45,2.8],[0,1.7,-3.6],'actual partial retention bridge'),guides=[-1,1].map(sign=>b([.7,.5,2.8],[sign*4,-1.7,-1.4],'actual mating guide')),contacts=[],returns=[],tails=[],barrels=[],pads=[];
 for(const x of[-3,-1,1,3]){contacts.push(b([.32,.32,6.5],[x,-.2,-3.85],'independent contact through retained backstop',tin()));returns.push(box(host.body,[.32,.32,.76],[x,-16.9,.98],tin(),'PaHub actual input right-angle return to raised PCB'));tails.push(box(host.body,[.32,.32,.8],[x,-16.9,.2],tin(),'PaHub input actual retained through-PCB tail'));barrels.push(ring(host.body,.36,.26,.8,[x,-16.9,-.2],tin(),'PaHub input actual plated receiving barrel'));for(const z of[-.225,.6])pads.push(ring(host.body,.65,.26,.025,[x,-16.9,z],tin(),'PaHub input actual annular solderland'));}
 const supports=[-3,3].map(x=>box(host.body,[1.1,2,1.7],[x,-21,-2.05],plastic(0xd5d5c7),'PaHub actual input dielectric support from rear native floor')),port=host.add(new Port({id:'grove',label:'PaHub v2.0 upstream mechanical Grove',connector:'grove',position:spec.input.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pinGrid:{cols:4,rows:1,pitch:2,center:[0,-.2],order:i=>4-i},pins:spec.pins.map((name,i)=>({n:i+1,name})),meta:{face:'bottom',role:'visual-connector',scope:'Mechanical input only;no I2C/address/routing/electrical/firmware'}}));return{frame,parts,floor,stop,walls,bridge,guides,contacts,returns,tails,barrels,pads,supports,port};}
function output(host,out){const frame=new THREE.Group();frame.position.fromArray(out.position);frame.rotation.z=out.rotation;frame.name='PaHub v2.0 actual upright '+out.id;host.body.add(frame);const red=plastic(0xb42d29),parts=[],b=(s,p,n,m=red)=>{const q=box(frame,s,p,m,'PaHub '+out.id+' '+n);parts.push(q);return q;},floor=b([10,5.2,.65],[0,0,-5.875],'actual retained PCB-side floor/stop'),walls=[-1,1].flatMap(sign=>[b([.7,5.2,6.2],[sign*4.65,0,-3.1],'actual long receiving side wall'),b([8.6,.6,6.2],[0,sign*2.3,-3.1],'actual receiving end wall')]),guides=[-1,1].map(sign=>b([.65,.7,1.4],[sign*3.95,1.65,-.7],'actual mouth retention guide')),contacts=[],stems=[],barrels=[],pads=[];
 for(let i=0;i<4;i++){const x=-3+2*i,[px,py]=outputPinXY(out,i);contacts.push(b([.32,.32,4.5],[x,-.2,-3.25],'independent actual upright metal contact',tin()));stems.push(box(host.body,[.32,.32,1.5],[px,py,.55],tin(),'PaHub '+out.id+' actual straight retained through-PCB stem'));barrels.push(ring(host.body,.36,.26,.8,[px,py,-.2],tin(),'PaHub '+out.id+' actual plated receiving barrel'));for(const z of[-.225,.6])pads.push(ring(host.body,.65,.26,.025,[px,py,z],tin(),'PaHub '+out.id+' actual annular solderland'));}
 const q=new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,0,1),out.rotation).multiply(portQuaternion('front')),port=host.add(new Port({id:out.id,label:'PaHub v2.0 physical channel '+out.channel,connector:'grove',position:out.position,quaternion:q,hitSize:[10,1,5.2],pinGrid:{cols:4,rows:1,pitch:2,center:[0,.2],order:i=>4-i},pins:spec.pins.map((name,i)=>({n:i+1,name})),meta:{face:'front',role:'visual-connector',printedChannel:out.channel,scope:'Independent mechanical connector only;no selection/address/polling/routing/electrical/firmware'}}));return{frame,parts,floor,walls,guides,contacts,stems,barrels,pads,port,position:out.position,rotation:out.rotation,channel:out.channel};}
function fixing(host){const shape=new THREE.Shape();shape.absarc(0,0,1.5,0,Math.PI*2,false);const hex=[];for(let i=0;i<6;i++)hex.push([.7*Math.cos(i/3*Math.PI),.7*Math.sin(i/3*Math.PI)]);shape.holes.push(polygon(hex));return{head:solid(host.body,shape,.45,[0,-12,-3.9],tin(),'PaHub actual retained rear hex-socket fixing head'),floor:cylinder(host.body,.9,.1,[0,-12,-3.4],plastic(0x292b26),'PaHub actual blind fixing recess floor'),shank:cylinder(host.body,.65,4.9,[0,-12,-1],tin(),'PaHub actual retained central screw shank')};}
export function buildPaHubV20(host){const shell=nativeShell(host),boardParts=board(host),chip=mux(host),upstream=input(host),outputs=spec.outputs.map(o=>output(host,o)),screw=fixing(host);host.pahubV20Assembly={frame:shell.front.parent,shell,board:boardParts,mux:chip,input:upstream,outputs,screw,nativeSource:source,nativeParts};host.unitStickers=addStickers(host);}
